import { yupResolver } from '@hookform/resolvers/yup';
import { Button, Dialog, DialogContent, DialogTitle, Slide, Stack } from '@mui/material';
import React from 'react';
import { useForm } from 'react-hook-form';
import * as Yup from 'yup';
import FormProvider from '../../components/hook-form/FormProvider';
import { RHFTextField } from '../../components/hook-form';
import RHFAutocomplete from '../../components/hook-form/RHFAutocomplete';


const Transition = React.forwardRef(function Transition(props, ref) {
    return <Slide direction="up" ref={ref} {...props} />;
});

const TAGS_OPTION = [
    "Toy Story 3",
    "Logan",
    "Full Metal Jacket",
    "Dangal",
    "The Sting",
    "2001: A Space Odyssey",
    "Singin' in the Rain",
    "Toy Story",
    "Bicycle Thieves",
    "The Kid",
    "Inglourious Basterds",
    "Snatch",
    "3 Idiots",
  ];


const CreateGroupForm = ({ handleClose }) => {
    const NewGroupSchema = Yup.object().shape({
        title: Yup.string().required("Title is required"),
        members: Yup.array().min(2, 'Group must have atleast 2 menbers'),
    })
    const defaultValues = {
        title: "",
        mumbers: [],
    }

    const methods = useForm({
        resolver: yupResolver(NewGroupSchema),
        defaultValues,

    })

    const { reset, watch, setError, handleSubmit, formState: { errors, isSubmitting, isSubmitSuccessful, isValid }, } = methods;

    const onSubmit = async (data) => {
        try {
            console.log("Data", data);
        } catch (error) {
            console.log("error", error)
        }
    };

    return (
        <>
            <FormProvider methods={methods} onSubmit={handleSubmit(onSubmit)}>
                <Stack spacing={3}>
                    <RHFTextField name='title' label='Title' />
                    <RHFAutocomplete name='members' label='Members' multiple freeSolo options={TAGS_OPTION.map((el) => el)} ChipProps={{ size: 'medium' }} />
                    <Stack spacing={2} direction={'row'} alignItems={'center'} justifyContent={'end'}>
                        <Button onClick={handleClose}>Cancel</Button>
                        <Button type='submit' variant='contained'>Create</Button>
                    </Stack>
                </Stack>
            </FormProvider>
        </>
    )
};

const CreateGroup = ({ open, handleClose }) => {

    return (
        <Dialog fullWidth maxWidth='xs' open={open} TransitionComponent={Transition} keepMounted sx={{ p: 4 }}>
            <Stack spacing={2}>
                <DialogTitle>Create New Group</DialogTitle>
                <DialogContent>
                    <CreateGroupForm handleClose={handleClose} />
                </DialogContent>
            </Stack>
        </Dialog>
    )
}

export default CreateGroup;